import{_ as t,c as n,j as e,a as l,o as _}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百五十五章 灭尽过去现在未来","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/255第二百五十五章 灭尽过去现在未来.md","filePath":"meditation/巴利文大藏经/255第二百五十五章 灭尽过去现在未来.md"}'),r={name:"meditation/巴利文大藏经/255第二百五十五章 灭尽过去现在未来.md"};function o(s,a,i,d,p,c){return _(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百五十五章-灭尽过去现在未来",tabindex:"-1"},[l("第二百五十五章 灭尽过去现在未来 "),e("a",{class:"header-anchor",href:"#第二百五十五章-灭尽过去现在未来","aria-label":'Permalink to "第二百五十五章 灭尽过去现在未来"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应46经/无常经第二(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！物质事物、物质身体、感受、念想、行为、认识、分别、判断是随时在变化的，是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的。物质事物是会衰败、灭亡、消失的，物质身体是会生病、衰老、死亡的。感受、念想、行为、认识、分别、判断是会消退、灭尽、消失的，既然如此，那么物质事物、物质身体、感受、念想、行为、认识、分别、判断最终带来的都是痛苦；物质事物、物质身体、感受、念想、行为、认识、分别、判断无法永远的存在，无法永恒的保持不变，无法永远的拥有，那么就没有真实不变的我存在，就没有青春永驻、永远不死的我存在，就没有可以永远拥有、永远存在、永远保持不变的物质事物、物质身体、感受、念想、行为、认识、分别、判断的存在。",-1),e("p",null,"比丘们！你们应该用正确的智慧，这样来看待物质事物、物质身体、感受、念想、行为、认识、分别、判断：「物质事物、物质身体、感受、念想、行为、认识、分别、判断不是我所拥有的，我不是这个物质事物、物质身体、感受、念想、行为、认识、分别、判断，这个物质事物、物质身体、感受、念想、行为、认识、分别、判断不是真实不变、永远存在的我。」简单的说就是：「这不是我的，我不是这个，这不是真实不变、永远存在的我。」当你们有这样正确的见解后，你们就不会再去回想、忆念过去的事情事物，你们就不会执着和挂念过去的事情事物；你们也不会再去幻想、推测未来的事物事情，不会执着和挂念未来的事物事情；你们更不会牢牢的抓住现在的事情事物不放，你们不会执着和挂念现在的事情事物。对于你们来说过去、现在、未来的时间分别、区别已经熄灭、消失、不存在了。过去、现在、未来这三个世间人安立出来的假名已经不在你们的内心中生起。",-1),e("p",null,"比丘们！当你们不再执着和挂念过去、现在、未来的事情事物的时候，当你们过去、现在、未来的时间分别、区别已经熄灭、消失、不存在的时候，你们的内心就不会被过去、现在、未来的物质事物、物质身体、感受、念想、行为、认识、分别、判断扰动、污染、影响而生起喜怒哀乐等等无数的念想，你们的内心就能长久的保持清净安宁，你们就不会再去执着和挂念过去、现在、未来的物质事物、物质身体、感受、念想、行为、认识、分别、判断，这样你们就不会再次产生忧愁、悲伤、苦闷、忧虑、绝望等等无数的烦恼和痛苦，就能最终从一切的烦恼和痛苦中解脱出来。",-1),e("p",null,"解脱后就能保持内心长久的清净安宁，内心清净安宁后就不会被世间一切的事物扰动、困惑、影响，就不会执着和挂念任何的念想，就不会生起任何的念想，没有执着，没有挂念，没有念想，就进入没有烦恼和痛苦的涅槃境界，就能彻底明白：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生的世间了，已经彻底从生死轮回中解脱出来。」",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
